using ExpandedLib.Testing;
using Newtonsoft.Json.Linq;
using PipesAndPowerExpanded.BlockStructures.Boiler.Blocks;
using Xunit;

namespace PipesAndPowerExpanded.Tests;

/// <summary>
/// Parity oracle for the boiler mega-blocks - the capstone code-first machines that exercise every builder
/// feature at once: the filler footprint and structure map drawn as ASCII layer diagrams, the geometry
/// offsets as generic attributes, and a multi-ingredient construction table. Comparison is via the shared
/// <see cref="DefinitionParity"/>, so the structure/filler tables match as unordered sets (a layer drawing of
/// the same cells is equivalent to the hand-written coordinate array). Goldens are the deleted JSON, minified.
/// </summary>
public class BoilerDefinitionParityTests
{
