  [Fact]
  public void Lancashire_def_reproduces_the_migrated_json()
  {
    JObject expected = JObject.Parse(LancashireGolden);
    JObject actual = BlockBoilerLancashire.Definitions("ppex").Single().ToJson();

    Assert.True(
      DefinitionParity.Equal(expected, actual, out string normalized),
      "Lancashire boiler def diverged from the migrated JSON. Normalized actual:\n" + normalized
    );
  }

  [Fact]
  public void Lancashire_targets_its_asset_location()
  {
    var loc = BlockBoilerLancashire.Definitions("ppex").Single().Location;
    Assert.Equal("ppex", loc.Domain);
    Assert.Equal("blocktypes/boiler/lancashire.json", loc.Path);
  }

